    'options.preset.intro.html': '三组可自定义的翻译预设，对应三组快捷键。依网页内容选择不同引擎或模型（例如文学性强用最强模型、一般网页用最省钱）。点各组右上方栏位后直接按下想要的组合键即可自定义（需包含 <strong>⌥ Option</strong> 或 <strong>⌃ Control</strong>，按 <strong>ESC</strong> 取消）；内建预设键仍然有效。已翻译状态下按任一快捷键都会还原原文；翻译中按任一快捷键则取消翻译。键位也可至 <a href="#" id="open-shortcuts" class="open-shortcuts-link">chrome://extensions/shortcuts</a> 变更',
