    'options.gemini.pricing.heading': '模型计价',
    'options.gemini.pricing.intro.html': 'Shinkansen 内置已知 Gemini 模型的标准层级单价（<strong id="pricing-calibrated-date">2026-09</strong> 校准），用于计算翻译成本显示在翻译完成通知与「用量记录」分页。Google 改价时可在下方覆盖对应模型，空白表示用内置价。详细费率见 <a href="https://ai.google.dev/pricing" target="_blank" rel="noopener">Gemini 官方定价页</a>',
    'options.gemini.pricing.priority': 'Preset 翻译的计价优先顺序：覆盖值 → 内置表 → 下方「后备路径单价」。单位皆为「每 1M tokens 的美金价格」',
