    'options.gemini.params.maxOutHint': 'Gemini 每次回复的最大 token 数量。数字越大，单批能翻译的内容越多，但也会消耗更多费用，上限 65,535，默认 8,192，一般不需要调整',
    'options.gemini.params.systemPromptLabel': '翻译 Prompt',
    'options.gemini.params.targetMismatch.html': '⚠ 你已自定义此 prompt；切换目标语言<strong>不会自动覆盖</strong>你的版本。要应用新目标语言默认，请清空字段保存（系统会自动走对应默认），或点下方「重置」按钮',

    'options.gemini.perf.summary': '性能调校（高级）— 批次大小、并发数量、单页段落上限、失败重试',
    'options.gemini.perf.intro': '调整每批翻译的大小与并发数量，影响翻译速度与质量的平衡。一般用户不需要动，维持默认即可',
    'options.gemini.perf.maxConcurrentLabel': '同时并发批次上限',
    'options.gemini.perf.maxConcurrentHint': '同时发送几批翻译请求。数字越大翻越快，但也越容易撞到配额上限，长文建议 5–10，短文可设 1（逐批翻译）',
    'options.gemini.perf.maxUnitsLabel': '每批段数上限',
    'options.gemini.perf.maxUnitsHint': '每一批最多包含几段。这里的「段」是指网页上一个独立的文字区块（例如一个段落、一个标题、一个列表项目），由网页结构自动检测。数字越大每批翻越多，但太大容易导致翻译对齐失准，默认 20',
    'options.gemini.perf.maxCharsLabel': '每批字符预算',
    'options.gemini.perf.maxCharsHint': '每一批累积的原文字符数上限（与段数上限先到先封口）。数字越大每批能装越多内容，但太大可能超出模型输出长度限制，默认 3500',
    'options.gemini.perf.maxTransLabel': '单页翻译段落上限',
    'options.gemini.perf.maxTransHint': '单次翻译最多处理几段。超大页面（如维基百科长条目）超过此上限时，多余段落会被略过。设为 0 表示不限制，默认 1000',

    'options.gemini.quota.retriesLabel': '失败重试次数',
    'options.gemini.quota.retriesHint': '单批翻译遇到 API 错误（如 429 配额限制）时的最大重试次数，设为 0 表示不重试、失败即跳过，默认 3 次',

    'options.gemini.resetAll': '重置所有参数',
    'options.gemini.resetAllTitle': '把本分页所有字段重置为默认值（会自动保存）',
    'options.gemini.resetAllConfirm': '确定要把 Gemini 分页所有参数重置为默认值吗？\n\n影响字段：Service Tier、模型计价覆盖（清空走内置表）、Tier/RPM/TPM/RPD、安全边际、重试次数、Temperature、Max Output Tokens、翻译 Prompt、并发批次、每批段数/字符/段落上限。\n\n按下后会自动保存。',
    'options.gemini.resetAllDone': '字段已重置并自动保存',

