    // ── options 自定义模型分页 ─────────────────────────────
    'options.cp.heading': '自定义 OpenAI 兼容模型',
    'options.cp.intro1': '想用 Gemini 之外的模型？设置一组 OpenAI 兼容端点即可接 OpenRouter（含 Anthropic / Gemini / Llama / Qwen / Grok 等百种模型）、Ollama 本地、Together、Groq、Fireworks、OpenAI 自家等',
    'options.cp.intro2': '设置完成后，到「常规设置」分页的「翻译快捷键」，把任一组预设引擎改为「自定义模型」，即可使用快捷键启动翻译',
    'options.cp.baseUrlLabel': 'Base URL',
    'options.cp.baseUrlPlaceholder': '例如：https://openrouter.ai/api/v1',
    'options.cp.baseUrlHint.html': 'OpenAI 兼容模型端点的根目录。系统会自动接 <code>/chat/completions</code>。常见：<code>https://openrouter.ai/api/v1</code>、<code>https://api.together.xyz/v1</code>、<code>http://localhost:11434/v1</code>（Ollama）',
    'options.cp.firefoxHttpsWarn.html': '⚠ <strong>Firefox 用户注意</strong>：Firefox 的 HTTPS-Only Mode 会把 <code>http://</code> 请求强制升级成 <code>https://</code>，导致连本地 server 失败。请到 <code>about:preferences#privacy</code> 滑到「HTTPS-Only Mode」改为「Don\'t enable」，或对该网址加入例外',
    'options.cp.cors.summary': '连本地 Ollama / llama.cpp 收到 403？（展开查看解法）',
    'options.cp.cors.line1.html': 'Chrome 从扩展功能调用本地后端（<code>localhost</code> / <code>127.0.0.1</code>）时，会强制发送 <code>Origin: chrome-extension://&lt;id&gt;</code> header。Ollama 与 llama.cpp 默认的 CORS 设置不认得这个 origin → 直接回 403',
    'options.cp.cors.line2.html': '<strong>两种解法择一</strong>：',
    'options.cp.cors.solution1.html': '<strong>Ollama</strong>：启动前设环境变量 <code>OLLAMA_ORIGINS=*</code>（或更严格的 <code>chrome-extension://*</code>）。macOS 用 <code>launchctl setenv OLLAMA_ORIGINS "*"</code> 后重启 Ollama；Windows 在「系统属性 → 环境变量」加 <code>OLLAMA_ORIGINS</code> = <code>*</code>',
    'options.cp.cors.solution2.html': '<strong>后端不能改 CORS 设置时</strong>：在系统 hosts 文件加一笔 <code>127.0.0.1 ollama.local</code>，Base URL 改成 <code>http://ollama.local:11434/v1</code>。Chrome 看到的不是 loopback 地址就不会强制发送 Origin',
    'options.cp.modelLabel': '模型 ID',
    'options.cp.modelPlaceholder': '例如：anthropic/claude-sonnet-4-5（llama.cpp / Ollama 可留空）',
    'options.cp.modelHint.html': 'OpenRouter 的 model ID 格式为 <code>provider/model</code>（如 <code>anthropic/claude-sonnet-4-5</code>、<code>google/gemini-3-flash</code>、<code>meta-llama/llama-3.1-70b</code>）；其他端点直接填 model 名称。本地 server（llama.cpp / Ollama）启动时若已锁定 model 可留空，request 不发送此字段即用 server 默认',
    'options.cp.apiKeyLabel': 'API Key',
    'options.cp.apiKeyPlaceholder': '粘贴对应 provider 的 API Key（本地 llama.cpp / Ollama 等可留空）',
    'options.cp.apiKeyHint': '仅存在你的浏览器本地（与 Gemini API Key 同样不跨设备同步、不上传任何服务器）；本地后端（llama.cpp / Ollama 等）可留空',
    'options.cp.systemPromptLabel': '翻译 Prompt',
    'options.cp.systemPromptPlaceholder': '留空使用内置简短默认 prompt',
    'options.cp.systemPromptHint': '自定义模型用独立的翻译 prompt（不继承 Gemini 分页的设置）；但「固定术语表」与「禁用词清单」会自动共用注入到 prompt 末端',
    'options.cp.resetPrompt': '重置为默认 Prompt（与 Gemini 同）',
    'options.cp.tempLabel': 'Temperature',
    'options.cp.tempHint': '留空 = 不发送 temperature 参数。部分推理模型只接受自家默认值，带了会直接失败',
    'options.cp.timeoutLabel': 'API 超时时间（秒）',
    'options.cp.timeoutHint': '每次 API 请求等待回应的最长时间。本地 LLM（Ollama 等）冷启动加载模型可能需要 120-300 秒，请根据硬件调高；商用 API 通常不需更改',
    'options.cp.advSummary': '高级：思考强度 / 段序号 / 超时 / 自定义 body',
    'options.cp.thinkingLabel': '思考强度',
    'options.cp.thinkingAuto': '自动（用 provider 默认）',
    'options.cp.thinkingOff': '关闭',
    'options.cp.thinkingLow': '低',
    'options.cp.thinkingMid': '中',
    'options.cp.thinkingHigh': '高',
    'options.cp.thinkingHint.html': '依 baseUrl 与模型自动翻译成对应 provider 的 thinking API（OpenRouter <code>reasoning.effort</code>、Claude <code>thinking.type</code>、OpenAI o-series <code>reasoning_effort</code>、Grok <code>reasoning_effort</code>、Qwen <code>extra_body.enable_thinking</code>）。翻译任务 thinking 通常无感但会多花 token；建议「关闭」省成本，除非你的模型只能在 thinking 开启时翻译（如 QwQ）。不认识的 provider 走「自动」',
    'options.cp.strongMarker': '强化段序号标记（适合本地量化模型）',
