    // ── options Gemini tab ───────────────────────────────
    'options.gemini.pricing.heading': 'Model pricing',
    'options.gemini.pricing.intro.html': 'Shinkansen has built-in Gemini standard tier prices (calibrated <strong id="pricing-calibrated-date">2026-09</strong>), used for translation cost shown in completion notifications and the "Usage history" tab. When Google changes prices, override per-model below; blank means use built-in price. See <a href="https://ai.google.dev/pricing" target="_blank" rel="noopener">Gemini official pricing page</a> for details',
    'options.gemini.pricing.priority': 'Preset translation pricing priority: override → built-in table → "Fallback path price" below. All units are USD per 1M tokens',
    'options.gemini.pricing.flashLite.builtin': 'Built-in $0.25 / $1.50',
