    'options.gemini.pricing.flashLite35.builtin': 'Built-in $0.30 / $2.50 (no caching)',
    'options.gemini.pricing.flash38.builtin': 'Built-in $0.75 / $3.75 (2026 intro price)',
    'options.gemini.pricing.cachedDiscountHint.html': 'The three columns are <strong>input / output price</strong> (USD/M tokens) and <strong>cache-hit discount</strong> (%, e.g. 90 = cached portion saves 90%). Gemini 2.5+ implicit cache defaults to 90% off',

    'options.gemini.partial.heading': 'Save mode',
    'options.gemini.partial.toggle': 'Translate only article opening',
    'options.gemini.partial.maxLabel': 'Max paragraphs to translate',
    'options.gemini.partial.hint': 'When enabled, translate only the first few paragraphs. Useful for quick previews to decide whether to keep reading; significantly reduces token usage. After translation a "Translate remaining paragraphs" button appears in the bottom corner—click to finish translation; previously translated paragraphs load from local cache without re-charging. Default 25, range 5-50',

    'options.gemini.params.heading': 'Model parameter tuning',
    'options.gemini.params.tempLabel': 'Temperature',
    'options.gemini.params.tempHint': 'Controls response randomness. Lower = more stable / consistent translations, higher = more creative but may drift, range 0–2, default 1.0 (Gemini 3 Flash factory default)',
    'options.gemini.params.advSummary': 'Advanced (Service Tier, Max Output Tokens)',
    'options.gemini.params.tierLabel': 'Service Tier — affects cost and latency',
    'options.gemini.params.tierDefault': 'Default (unspecified, safe / compatible)',
    'options.gemini.params.tierFlex': 'Flex (50% off, but noticeably slower)',
    'options.gemini.params.tierStandard': 'Standard (regular price)',
    'options.gemini.params.tierPriority': 'Priority (priority, more expensive)',
    'options.gemini.params.tierHint': 'Note: Service Tier is only supported by newer models (e.g. gemini-3-flash-preview); use "Default" for older models to avoid errors',
    'options.gemini.params.maxOutHint': 'Max tokens per Gemini response. Larger = more content per batch but higher cost, max 65,535, default 8,192, generally no need to adjust',
    'options.gemini.params.systemPromptLabel': 'Translation Prompt',
    'options.gemini.params.targetMismatch.html': '⚠ You have customized this prompt; switching target language <strong>will not auto-overwrite</strong> your version. To apply the new target language default, clear the field and save (system uses corresponding default), or click the "Reset" button below',

    'options.gemini.perf.summary': 'Performance tuning (advanced) — batch size, concurrency, page paragraph limit, retries',
    'options.gemini.perf.intro': 'Adjust batch size and concurrency, balancing translation speed and quality. General users do not need to change this; defaults are fine',
    'options.gemini.perf.maxConcurrentLabel': 'Max concurrent batches',
    'options.gemini.perf.maxConcurrentHint': 'How many translation requests to send concurrently. Higher = faster, but easier to hit quota; long articles 5–10, short ones can use 1 (sequential)',
    'options.gemini.perf.maxUnitsLabel': 'Max paragraphs per batch',
    'options.gemini.perf.maxUnitsHint': 'Max paragraphs per batch. A "paragraph" is an independent text block on the page (e.g. a paragraph, heading, list item), auto-detected from page structure. Higher = more per batch, but too high causes alignment issues, default 20',
    'options.gemini.perf.maxCharsLabel': 'Char budget per batch',
    'options.gemini.perf.maxCharsHint': 'Max original characters per batch (whichever cap hits first with paragraph cap). Higher = more content per batch, but too high may exceed model output length, default 3500',
    'options.gemini.perf.maxTransLabel': 'Max paragraphs per page',
    'options.gemini.perf.maxTransHint': 'Max paragraphs to translate in one go. Very large pages (e.g. long Wikipedia articles) exceeding this limit will skip extras. Set to 0 for no limit, default 1000',

    'options.gemini.quota.retriesLabel': 'Failure retry count',
    'options.gemini.quota.retriesHint': 'Max retries when a single batch translation hits an API error (e.g. 429 quota limit). Set to 0 to skip on failure (no retries), default 3',

    'options.gemini.resetAll': 'Reset all params',
    'options.gemini.resetAllTitle': 'Reset all fields on this tab to defaults (saved automatically)',
    'options.gemini.resetAllConfirm': 'Reset all Gemini tab params to defaults?\n\nAffected fields: Service Tier, model pricing override (clear → use built-in table), Tier/RPM/TPM/RPD, safety margin, retry count, Temperature, Max Output Tokens, Translation Prompt, concurrent batches, paragraphs/chars/page limit per batch.\n\nSaved automatically.',
    'options.gemini.resetAllDone': 'Fields reset and auto-saved',

