    // ── options 翻訳ショートカット ───────────────────────────
    'options.preset.heading': '翻訳ショートカット',
    'options.preset.intro.html': '3 組のカスタマイズ可能な翻訳プリセットがあり、それぞれショートカットに対応します。ページ内容に応じてエンジンやモデルを切り替えられます（文学的な内容は最強モデル、一般ページは最も安価など）。各プリセット右上の欄をクリックし、使いたい組み合わせを押すと設定できます（<strong>⌥ Option</strong> または <strong>⌃ Control</strong> を含める必要があります。<strong>ESC</strong> でキャンセル）。内蔵のデフォルトキーも引き続き有効です。翻訳済みの状態で任意のショートカットを押すと原文に戻り、翻訳中ならキャンセルします。キー設定は <a href="#" id="open-shortcuts" class="open-shortcuts-link">chrome://extensions/shortcuts</a> でも変更できます',
    'options.preset.introSafari.html': '3 組のカスタマイズ可能な翻訳プリセットがあり、それぞれショートカットに対応します。ページ内容に応じてエンジンやモデルを切り替えられます（文学的な内容は最強モデル、一般ページは最も安価など）。各プリセット右上の欄をクリックし、使いたい組み合わせを押すと設定できます（<strong>⌃ Control</strong> を使ってください。<strong>ESC</strong> でキャンセル）。内蔵のデフォルトキーも引き続き有効です。翻訳済みの状態で任意のショートカットを押すと原文に戻り、翻訳中ならキャンセルします',
    'options.preset.introIos.html': '<strong>iOS／iPadOS</strong>：ページを 4 本指でタップすると翻訳できます（メインプリセットと同じ）。もう一度タップすると原文に戻る、または翻訳をキャンセルします。4 本指の長押しではサブプリセットを使います（デフォルトは高品質の Gemini 3.8 Flash）。ハードウェアキーボード接続時は内蔵のデフォルトショートカットがそのまま使えます',
    'options.preset.restoreDefault': 'デフォルトに戻す',
