    'options.gemini.pricing.heading': 'モデル料金',
    'options.gemini.pricing.intro.html': 'Shinkansen には主要な Gemini モデルの標準ティア単価が組み込まれており（<strong id="pricing-calibrated-date">2026-09</strong> 校正）、翻訳完了通知と「使用量履歴」タブで翻訳コストを計算します。Google が価格を変更した際は下のフィールドで該当モデルを上書きできます。空欄なら組み込み価格を使用。詳細は <a href="https://ai.google.dev/pricing" target="_blank" rel="noopener">Gemini 公式料金ページ</a> をご覧ください',
    'options.gemini.pricing.priority': 'プリセット翻訳の料金優先順位：上書き値 → 組み込み表 → 下の「フォールバック単価」。単位はすべて「100 万トークンあたりの USD」',
    'options.gemini.pricing.flashLite.builtin': '組み込み $0.25 / $1.50',
