    'options.gemini.pricing.flashLite35.builtin': '組み込み $0.30 / $2.50（キャッシュ非対応）',
    'options.gemini.pricing.flash38.builtin': '組み込み $0.75 / $3.75（2026 年プロモ価格）',
    'options.gemini.pricing.cachedDiscountHint.html': '3 つの列は順に <strong>input / output 単価</strong>（USD/M tokens）と <strong>cache ヒット割引</strong>（%、例：90 = ヒット部分は 90% 節約）。Gemini 2.5 以降、implicit cache はデフォルト 90% off',

    'options.gemini.partial.heading': '節約モード',
    'options.gemini.partial.toggle': '記事冒頭のみ翻訳',
    'options.gemini.partial.maxLabel': '翻訳段落数の上限',
    'options.gemini.partial.hint': '有効時はページの最初の数段落のみ翻訳します。プレビューしてから読み続けるか判断する場合に適しており、トークン使用量を大幅に削減できます。翻訳完了後、右下の通知に「残りの段落を翻訳」ボタンが表示され、クリックすれば全文翻訳を続行できます。既訳分はローカルキャッシュから読み込まれ、再課金されません。デフォルト 25 段、範囲 5–50',

    'options.gemini.params.heading': 'モデルパラメータ調整',
    'options.gemini.params.tempLabel': 'Temperature',
    'options.gemini.params.tempHint': '応答のランダム性を制御します。数値が低いほど翻訳が安定し一貫し、高いほど創造的になりますが原意から外れる可能性があります。範囲 0–2、デフォルト 1.0（Gemini 3 Flash の標準値）',
    'options.gemini.params.advSummary': '詳細設定（Service Tier、Max Output Tokens）',
    'options.gemini.params.tierLabel': 'Service Tier — コストとレイテンシに影響',
    'options.gemini.params.tierDefault': 'デフォルト（指定なし、安全互換）',
    'options.gemini.params.tierFlex': 'Flex（50% 節約、ただし翻訳速度が明らかに遅くなる）',
    'options.gemini.params.tierStandard': 'Standard（標準価格）',
    'options.gemini.params.tierPriority': 'Priority（優先、より高価）',
    'options.gemini.params.tierHint': '注意：Service Tier は新しいモデル（gemini-3-flash-preview など）のみ対応します。古いモデルでは「デフォルト」を使用してエラーを避けてください',
    'options.gemini.params.maxOutHint': 'Gemini が 1 回の応答で生成する最大トークン数。数値が大きいほど 1 バッチで翻訳できる量が増えますが、コストも増えます。上限 65,535、デフォルト 8,192、通常は調整不要',
    'options.gemini.params.systemPromptLabel': '翻訳プロンプト',
    'options.gemini.params.targetMismatch.html': '⚠ このプロンプトをカスタマイズしています。目標言語を切り替えても<strong>自動的に上書きされません</strong>。新しい目標言語のデフォルトを適用するには、フィールドを空にして保存（システムが対応するデフォルトを自動使用）するか、下の「リセット」ボタンを押してください',

    'options.gemini.perf.summary': 'パフォーマンス調整（詳細）— バッチサイズ、並行数、ページあたり段落上限、リトライ',
    'options.gemini.perf.intro': '各翻訳バッチのサイズと並行数を調整します。翻訳速度と品質のバランスに影響しますが、一般ユーザーは調整不要です',
    'options.gemini.perf.maxConcurrentLabel': '同時並行バッチの上限',
    'options.gemini.perf.maxConcurrentHint': '同時に送信する翻訳リクエスト数。数値が大きいほど高速ですが、クォータ上限に達しやすくなります。長文は 5–10、短文は 1（バッチごと）を推奨',
    'options.gemini.perf.maxUnitsLabel': '1 バッチあたりの段落上限',
    'options.gemini.perf.maxUnitsHint': '1 バッチに含める最大段落数。ここでの「段」はページ上の独立したテキストブロック（段落、見出し、リスト項目など）を指し、ページ構造から自動検出されます。数値が大きいほど 1 バッチで多く翻訳できますが、大きすぎると翻訳のアラインメントがずれやすくなります。デフォルト 20',
    'options.gemini.perf.maxCharsLabel': '1 バッチあたりの文字予算',
    'options.gemini.perf.maxCharsHint': '1 バッチで累積する原文字数の上限（段落数上限と先着で確定）。数値が大きいほど 1 バッチに多くの内容が入りますが、大きすぎるとモデル出力長制限を超える可能性があります。デフォルト 3500',
    'options.gemini.perf.maxTransLabel': 'ページあたり翻訳段落上限',
    'options.gemini.perf.maxTransHint': '1 回の翻訳で処理する最大段落数。超大型ページ（Wikipedia の長い項目など）でこの上限を超えると、超過分はスキップされます。0 で無制限、デフォルト 1000',

    'options.gemini.quota.retriesLabel': '失敗リトライ回数',
    'options.gemini.quota.retriesHint': '1 バッチ翻訳で API エラー（429 クォータ制限など）に遭遇した際の最大リトライ回数。0 でリトライなし（失敗時はスキップ）、デフォルト 3 回',

    'options.gemini.resetAll': 'すべてのパラメータをリセット',
    'options.gemini.resetAllTitle': 'このタブのすべてのフィールドをデフォルトにリセット（自動的に保存されます）',
    'options.gemini.resetAllConfirm': 'Gemini タブのすべてのパラメータをデフォルトにリセットしますか？\n\n影響するフィールド：Service Tier、モデル料金上書き（クリアして組み込み表へ）、Tier/RPM/TPM/RPD、安全マージン、リトライ回数、Temperature、Max Output Tokens、翻訳プロンプト、並行バッチ、バッチごと段落 / 文字 / 段落上限。\n\n押すと自動的に保存されます。',
    'options.gemini.resetAllDone': 'フィールドをリセットし自動保存しました',

    // ── options Gemini cost-hint(動的 yt-prompt-cost-hint) ─
    'options.gemini.cost.googleHint.html': '<strong>Google Translate はプロンプトを送信しません</strong>。これら 2 つのトグルは Google MT には適用されません',
    'options.gemini.cost.noPrice.html': '<strong>コスト推定不可</strong>：対応する料金フィールドで input 単価（USD / 1M tokens）を設定してください',
    'options.gemini.cost.estimateHeader.html': '<strong>token コスト推定</strong>（現在のモデル <code>{model}</code> 基準、input ${inputPrice}/1M tokens、30 分動画で約 60 バッチ）：',
    'options.gemini.cost.estimateGlossary.html': '• 「固定用語集」適用（{count} 件）→ 1 バッチあたり prompt +{tok} token、全動画で約 {usd}（cache ヒット後 ~{usdCache}）',
    'options.gemini.cost.estimateForbidden.html': '• 「禁止語リスト」適用（{count} 件）→ 1 バッチあたり prompt +{tok} token、全動画で約 {usd}（cache ヒット後 ~{usdCache}）',
    'options.gemini.cost.estimateFooter.html': '※ token は概算で、実際は Gemini tokenizer に依存します。Gemini implicit cache のヒットには prompt prefix が ≥1024 token かつ安定している必要があり、ヒット部分は {pct}% で課金されます',

