    // ── options 번역 단축키 ───────────────────────────────
    'options.preset.heading': '번역 단축키',
    'options.preset.intro.html': '커스터마이즈 가능한 번역 프리셋 3개가 있으며, 각각 단축키에 대응합니다. 페이지 콘텐츠에 따라 다른 엔진이나 모델을 선택할 수 있습니다(예: 문학적인 내용은 가장 강한 모델, 일반 페이지는 가장 저렴한 모델). 각 프리셋 오른쪽 위 칸을 클릭하고 원하는 조합을 누르면 설정됩니다(<strong>⌥ Option</strong> 또는 <strong>⌃ Control</strong>을 포함해야 하며, <strong>ESC</strong>로 취소). 기본 내장 키도 계속 작동합니다. 번역된 상태에서 임의의 단축키를 누르면 원문으로 복원되고, 번역 중에는 번역이 취소됩니다. 키 설정은 <a href="#" id="open-shortcuts" class="open-shortcuts-link">chrome://extensions/shortcuts</a>에서도 변경할 수 있습니다',
    'options.preset.introSafari.html': '커스터마이즈 가능한 번역 프리셋 3개가 있으며, 각각 단축키에 대응합니다. 페이지 콘텐츠에 따라 다른 엔진이나 모델을 선택할 수 있습니다(예: 문학적인 내용은 가장 강한 모델, 일반 페이지는 가장 저렴한 모델). 각 프리셋 오른쪽 위 칸을 클릭하고 원하는 조합을 누르면 설정됩니다(<strong>⌃ Control</strong> 사용, <strong>ESC</strong>로 취소). 기본 내장 키도 계속 작동합니다. 번역된 상태에서 임의의 단축키를 누르면 원문으로 복원되고, 번역 중에는 번역이 취소됩니다',
    'options.preset.introIos.html': '<strong>iOS / iPadOS</strong>: 네 손가락으로 페이지를 탭하면 번역됩니다(기본 프리셋과 동일). 다시 탭하면 원문 복원 또는 번역 취소됩니다. 네 손가락 길게 누르기는 보조 프리셋을 사용합니다(기본값은 품질이 높은 Gemini 3.8 Flash). 하드웨어 키보드 연결 시 기본 내장 단축키는 그대로 사용할 수 있습니다',
