    'options.gemini.pricing.heading': '모델 가격',
    'options.gemini.pricing.intro.html': 'Shinkansen은 알려진 Gemini 모델의 표준 등급 단가가 내장되어 있으며 (<strong id="pricing-calibrated-date">2026-09</strong> 보정됨), 번역 비용을 계산하여 번역 완료 알림과 "사용 기록" 탭에 표시합니다. Google이 가격을 변경할 때 아래에서 해당 모델을 덮어쓸 수 있으며, 비워두면 내장 가격을 사용합니다. 자세한 요율은 <a href="https://ai.google.dev/pricing" target="_blank" rel="noopener">Gemini 공식 가격 페이지</a>를 참조하세요',
