    'options.glossary.auto.intro.html': '장문 번역 시 먼저 번역 엔진을 호출하여 전체 텍스트의 고유명사를 추출하고 매핑 테이블을 만들어 배치 번역의 명사 번역 일관성을 보장합니다. 단문 (1 배치 이내)은 자동으로 건너뜁니다. 기본 비활성화 — 활성화 후 용어 번역은 번역 Prompt의 일부 지시를 건너뜁니다 (예: "영어 인명 보존"이 무효화됨). 자세한 설명은 <a href="https://github.com/jimmysu0309/shinkansen#術語表一致化" target="_blank" rel="noopener">README</a> 참조',
