    // ── options atajos de traducción ───────────────────────────
    'options.preset.heading': 'Atajos de traducción',
    'options.preset.intro.html': 'Tres preajustes de traducción personalizables, cada uno asociado a un atajo. Elige distintos motores o modelos según el contenido (por ejemplo, el modelo más potente para texto literario; el más barato para páginas comunes). Haz clic en el campo de un preajuste y pulsa la combinación que quieras (debe incluir <strong>⌥ Option</strong> o <strong>⌃ Control</strong>; pulsa <strong>ESC</strong> para cancelar); las teclas predeterminadas integradas siguen funcionando. Si la página ya está traducida, cualquier atajo restaura el original; durante la traducción, cualquier atajo la cancela. Las teclas también se pueden cambiar en <a href="#" id="open-shortcuts" class="open-shortcuts-link">chrome://extensions/shortcuts</a>',
    'options.preset.introSafari.html': 'Tres preajustes de traducción personalizables, cada uno asociado a un atajo. Elige distintos motores o modelos según el contenido (por ejemplo, el modelo más potente para texto literario; el más barato para páginas comunes). Haz clic en el campo de un preajuste y pulsa la combinación que quieras (usa <strong>⌃ Control</strong>; pulsa <strong>ESC</strong> para cancelar); las teclas predeterminadas integradas siguen funcionando. Si la página ya está traducida, cualquier atajo restaura el original; durante la traducción, cualquier atajo la cancela',
    'options.preset.introIos.html': '<strong>iOS / iPadOS</strong>: toca la página con cuatro dedos para traducir (igual que el preajuste principal); toca de nuevo para restaurar el original o cancelar. Un toque prolongado con cuatro dedos usa el preajuste secundario (Gemini 3.8 Flash, de mayor calidad, de forma predeterminada). Con un teclado físico conectado, los atajos predeterminados integrados funcionan con normalidad',
    'options.preset.restoreDefault': 'Restaurar predeterminado',
    'shortcut.recording': 'Pulsa las teclas…',
    'shortcut.defaultSuffix': '{key} (predet.)',
    'shortcut.invalid.needKey': 'Pulsa una combinación que incluya una tecla normal',
    'shortcut.invalid.esc': 'ESC está reservada para cancelar la grabación',
    'shortcut.invalid.needMod': 'La combinación debe incluir ⌥ o ⌃ (para no activarse al escribir)',
    'shortcut.invalid.isDefault': '{key} ya es un atajo predeterminado integrado',
    'shortcut.invalid.assigned': '{key} ya está asignado a otro preajuste',
    'shortcut.invalid.safariNeedCtrl': 'En Safari usa una combinación ⌃ Control',
    'options.preset.firefoxWarn.html': '⚠ <strong>Aviso para usuarios de Firefox</strong>: en Firefox <code>Alt+S</code> abre el menú "Historial", <code>Alt+D</code> va a la barra de direcciones y <code>Alt+A</code> también suele ser interceptada por otras extensiones (como Save Page WE). Chrome no tiene este conflicto, pero en Firefox los tres atajos preajustados pueden no disparar la traducción. Ve a <code>about:addons</code> → icono de ajustes (engranaje) → "Administrar accesos directos de extensiones" y cámbialos a combinaciones sin conflicto (por ejemplo, <code>Ctrl+Shift+S</code>)',
