    // ── options pestaña Debug ───────────────────────────────
    'options.log.youtube.heading': 'Subtítulos de YouTube',
    'options.log.youtube.debugToast': 'Mostrar panel de estado en tiempo real de la traducción de subtítulos',
    'options.log.youtube.debugToastHint.html': 'Si está activado, al iniciarse la traducción de subtítulos aparecerá en la esquina superior izquierda un panel de estado en tiempo real que muestra buffer, latencia de batch API, tamaño de captionMap y otros datos diagnósticos. Para el significado de cada campo consulta <a href="https://github.com/jimmysu0309/shinkansen/blob/main/DEBUG-BOARD.md" target="_blank" rel="noopener">DEBUG-BOARD.md</a>',
    'options.log.youtube.onTheFly': 'Activar traducción de respaldo On-the-fly',
    'options.log.youtube.onTheFlyHint': 'Si está activado, cuando aparezca un subtítulo no pretraducido (no hay hit en captionMap), se enviará a la API en el momento. Si usas un modelo lento (Flash Lite, etc.) se recomienda desactivarlo para que las solicitudes en vivo no bloqueen la pretraducción. Desactivado por defecto',
