    // ── options raccourcis de traduction ───────────────────────────
    'options.preset.heading': 'Raccourcis de traduction',
    'options.preset.intro.html': 'Trois préréglages de traduction personnalisables associés à trois raccourcis. Choisissez le moteur ou modèle selon le contenu (par exemple, modèle le plus puissant pour le littéraire, le plus économique pour le grand public). Cliquez sur le champ d\'un préréglage et appuyez sur la combinaison souhaitée (doit inclure <strong>⌥ Option</strong> ou <strong>⌃ Control</strong> ; appuyez sur <strong>ESC</strong> pour annuler) ; les touches par défaut intégrées fonctionnent toujours. Une fois traduit, n\'importe quel raccourci restaure l\'original ; pendant la traduction, n\'importe quel raccourci l\'annule. Les touches peuvent aussi se changer dans <a href="#" id="open-shortcuts" class="open-shortcuts-link">chrome://extensions/shortcuts</a>',
    'options.preset.introSafari.html': 'Trois préréglages de traduction personnalisables associés à trois raccourcis. Choisissez le moteur ou modèle selon le contenu (par exemple, modèle le plus puissant pour le littéraire, le plus économique pour le grand public). Cliquez sur le champ d\'un préréglage et appuyez sur la combinaison souhaitée (utilisez <strong>⌃ Control</strong> ; appuyez sur <strong>ESC</strong> pour annuler) ; les touches par défaut intégrées fonctionnent toujours. Une fois traduit, n\'importe quel raccourci restaure l\'original ; pendant la traduction, n\'importe quel raccourci l\'annule',
    'options.preset.introIos.html': '<strong>iOS / iPadOS</strong> : touchez la page avec quatre doigts pour traduire (comme le préréglage principal) ; touchez à nouveau pour restaurer l\'original ou annuler. Un appui long à quatre doigts utilise le préréglage secondaire (Gemini 3.8 Flash, de meilleure qualité, par défaut). Avec un clavier physique connecté, les raccourcis par défaut intégrés fonctionnent normalement',
    'options.preset.restoreDefault': 'Rétablir par défaut',
    'shortcut.recording': 'Appuyez sur les touches…',
