    'doc.settingsPage.section.quality.title': 'Qualité de la traduction',
    'doc.settingsPage.section.quality.note.html': 'L\'option « Construire automatiquement le glossaire avant la traduction » a été remplacée par la fonction <strong>glossaire de l\'article</strong> (v1.8.49) : sur l\'écran principal, cliquez sur « Créer d\'abord le glossaire de l\'article » et l\'IA en extraira un que vous pourrez modifier, importer et exporter en JSON. Chaque article est indépendant et n\'est pas conservé ; exportez en JSON si vous voulez le garder entre sessions.',
    'doc.settingsPage.applyFixedGlossary': 'Appliquer mon glossaire fixe',
    'doc.settingsPage.applyFixedGlossary.hint': 'Utilise le glossaire fixe modifié dans « Paramètres → Glossaire » (partagé avec la traduction web). Par exemple, mapper Tokyo→Tokyo applique cette traduction à chaque document.',
    'doc.settingsPage.section.prompt.title': 'Prompt de traduction',
    'doc.settingsPage.section.prompt.hint.html': 'Voici le system prompt envoyé à l\'IA. Vous pouvez personnaliser le style de traduction, les préférences de vocabulaire et les règles d\'emphase — par exemple « traduisez sur un ton journalistique » ou « préservez tous les noms d\'entreprises en anglais ». <strong>N\'affecte que la traduction de documents ; ne change rien à la traduction web.</strong> La plupart des utilisateurs n\'ont pas besoin de modifier ceci.',
    'doc.settingsPage.btn.resetPrompt': 'Réinitialiser à la valeur par défaut',
    'doc.settingsPage.section.advanced.title': 'Avancé',
    'doc.settingsPage.label.temperature': 'Créativité de traduction (temperature)',
    'doc.settingsPage.hint.temperature': 'Des valeurs plus basses rendent les traductions plus stables (noms/termes cohérents, vocabulaire conservateur) ; plus hautes, plus créatives (prose plus fluide mais possiblement déviante). Plage 0–2, défaut 0.5. Contrats/documents techniques : 0.3–0.5 ; essais/articles : ~1. Changer cette valeur retraduit automatiquement le même document (l\'ancienne traduction n\'est pas réutilisée).',
    'doc.settingsPage.danger.title': 'Effacer toute la mémoire de traduction de documents',
    'doc.settingsPage.danger.hint.html': 'Chaque traduction est mise en cache localement, donc la prochaine fois que le même texte est traduit, il est réutilisé gratuitement. Ce bouton efface le cache de tous les documents — re-traduire un document précédent rappellera l\'IA (consommant des tokens). <br>À utiliser quand : vous avez changé le prompt ci-dessus et voulez tout retraduire, ou les anciennes traductions vous semblent médiocres et vous voulez recommencer.<br><strong>La traduction web, la traduction de sous-titres et la mémoire du glossaire ne sont pas affectées.</strong>',
    'doc.settingsPage.btn.clearAllCache': 'Effacer toute la mémoire de traduction de documents',
